# Debug the actual check_container function
def check_container(row, col, bg=6, fg=4):
    if row[col] != bg:
        return False
    # Look left for a fg
    has_left_fg = False
    for c in range(col-1, -1, -1):
        if row[c] == fg:
            has_left_fg = True
            break
        if row[c] == bg:
            # Found bg without a fg
            return False

    # Look right for a fg
    has_right_fg = False
    for c in range(col+1, len(row)):
        if row[c] == fg:
            has_right_fg = True
            break
        if row[c] == bg:
            # Found bg without a fg
            return False

    return has_left_fg and has_right_fg

